    .in_1( s5 ),
    .in_2( s22 ),
    .in_3( s22 ),
    .out( next_pc )
  );
  Mux_2x1_NBits #(
    .Bits(6)
  )
  Mux_2x1_NBits_i10 (
    .sel( step ),
    .in_0( pc_temp ),
    .in_1( next_pc ),
    .out( s23 )
  );
  programCounter programCounter_i11 (
    .C( clk ),
    .in( s23 ),
    .ld( 1'b1 ),
    .clr( pc_clr ),
    .out( pc_temp )
  );
  DIG_Add #(
    .Bits(6)
  )
  DIG_Add_i12 (
    .a( pc_temp ),
    .b( 6'b1 ),
    .c_i( 1'b0 ),
    .s( s22 )
  );
  assign pc = pc_temp;
endmodule

module sbc (
  input clk,
  input s1_n, // S1, 0 when pressed: go to run mode
  input s2_n, // S2, 0 when pressed: reset
  input run_n, // RUN, 0 when pressed
  input [7:0] dip_n, // DIP switch, ON = 0
  input back_n, // BACK, 0 when pressed
  input enter_n, // ENTER / STEP, 0 when pressed
  output [5:0] addr, // entry address (program mode) or PC (run mode)
  output [13:0] instr, // instruction at addr
  output [3:0] out, // output port Mem[14]
  output [2:0] led_n // LED0-2, 0 = on

);
  wire [5:0] addr_temp;
  wire [13:0] instr_temp;
  wire s0;
  wire s1;
  wire s2;
  wire s3;
  wire s4;
  wire [7:0] dip;
  wire s5;
  wire s6;
  wire s7;
  wire SW3;
  wire [5:0] pc;
  wire mode;
  wire lo;
  wire [5:0] s8;
  wire s9;
  wire s10;
  wire pc_clr;
  wire running;
  wire step;
  wire [5:0] s11;
  wire [5:0] s12;
  wire [7:0] s13;
  wire [2:0] s14;
  EdgeDetector EdgeDetector_i0 (
    .clk( clk ),
    .btn_n( s1_n ),
    .press( s0 )
  );
  EdgeDetector EdgeDetector_i1 (
    .clk( clk ),
    .btn_n( enter_n ),
    .press( s1 )
  );
  EdgeDetector EdgeDetector_i2 (
    .clk( clk ),
    .btn_n( back_n ),
    .press( s2 )
  );
  EdgeDetector EdgeDetector_i3 (
    .clk( clk ),
    .btn_n( run_n ),
    .press( s3 )
  );
  // s2_sample
  DIG_D_FF_1bit #(
    .Default(0)
  )
  DIG_D_FF_1bit_i4 (
    .D( s2_n ),
    .C( clk ),
    .\~Q ( s4 )
  );
  assign dip = ~ dip_n;
  assign s5 = dip[0];
  assign s6 = dip[1];
  assign s7 = dip[2];
  assign SW3 = dip[3];
  assign s11 = dip[5:0];
  FrontPanel FrontPanel_i5 (
    .clk( clk ),
    .reset( s4 ),
    .s1_press( s0 ),
    .enter_press( s1 ),
    .back_press( s2 ),
    .run_press( s3 ),
    .instr( instr_temp ),
    .pc( pc ),
    .mode( mode ),
    .lo( lo ),
    .entry_addr( s8 ),
    .write_H( s9 ),
    .write_L( s10 ),
    .pc_clr( pc_clr ),
    .running( running ),
    .step( step )
  );
  // RAM_H
  DIG_RAMDualPort #(
    .Bits(6),
    .AddrBits(6)
  )
  DIG_RAMDualPort_i6 (
    .A( addr_temp ),
    .Din( s11 ),
    .str( s9 ),
    .C( clk ),
    .ld( 1'b1 ),
    .D( s12 )
  );
  // RAM_L
  DIG_RAMDualPort #(
    .Bits(8),
    .AddrBits(6)
  )
  DIG_RAMDualPort_i7 (
    .A( addr_temp ),
    .Din( dip ),
    .str( s10 ),
    .C( clk ),
    .ld( 1'b1 ),
    .D( s13 )
  );
  CPU_sbc CPU_sbc_i8 (
    .clk( clk ),
    .step( step ),
    .pc_clr( pc_clr ),
    .instr( instr_temp ),
    .SW0( s5 ),
    .SW1( s6 ),
    .SW2( s7 ),
    .SW3( SW3 ),
    .pc( pc ),
    .out( out )
  );
  Mux_2x1_NBits #(
    .Bits(6)
  )
  Mux_2x1_NBits_i9 (
    .sel( mode ),
    .in_0( s8 ),
    .in_1( pc ),
    .out( addr_temp )
  );
  assign instr_temp[7:0] = s13;
  assign instr_temp[13:8] = s12;
  assign s14[0] = mode;
  assign s14[1] = (lo & ~ mode);
  assign s14[2] = running;
  assign led_n = ~ s14;
  assign addr = addr_temp;
  assign instr = instr_temp;
endmodule
